<?php get_header(); ?><main class="container content-area py-5"><?php if(have_posts()):while(have_posts()):the_post(); ?><article class="article-card mb-4"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><div class="entry-meta"><?php echo esc_html(get_the_date()); ?></div><?php the_excerpt(); ?><a class="text-arrow" href="<?php the_permalink(); ?>">Read more <i class="bi bi-arrow-right"></i></a></article><?php endwhile;newtheme_pagination();else: ?><p>No content found.</p><?php endif; ?></main><?php get_footer(); ?>